// SPDX-License-Identifier: Apache-2.0
pragma solidity 0.8.19;

import {ECDSA} from "./ECDSA.sol";

struct OracleAttestationData {
    bytes32 queryId;
    ReportData report;
    uint256 attestationTimestamp;//timestamp of validatorSignatures on report
}

struct ReportData {
    bytes value;
    uint256 timestamp;//timestamp of reporter signature aggregation
    uint256 aggregatePower;
    uint256 previousTimestamp;
    uint256 nextTimestamp;
    uint256 lastConsensusTimestamp;
}

struct Signature {
    uint8 v;
    bytes32 r;
    bytes32 s;
}

struct Validator {
    address addr;
    uint256 power;
}


/// @title TellorDataBridge: Tellor Layer -> EVM, Oracle relay.
/// @dev The relay relies on a set of signers to attest to some event on
/// Tellor Layer. These signers are the validator set, who sign over every
/// block. At least 2/3 of the voting power of the current
/// view of the validator set must sign off on new relayed events.
contract TellorDataBridge is ECDSA {

    /*Storage*/
    address public guardian; /// Able to reset the validator set only if the validator set becomes stale.
    bytes32 public lastValidatorSetCheckpoint; ///Domain-separated commitment to the latest validator set.
    uint256 public powerThreshold; /// Voting power required to submit a new update.
    uint256 public unbondingPeriod; /// Time period after which a validator can withdraw their stake.
    uint256 public validatorTimestamp; /// Timestamp of the block where validator set is updated.
    address public deployer; /// Address that deployed the contract.
    bool public initialized; /// True if the contract is initialized.
    uint256 public constant MS_PER_SECOND = 1000; // factor to convert milliseconds to seconds
    bytes32 public constant NEW_REPORT_ATTESTATION_DOMAIN_SEPARATOR = // "tellorCurrentAttestation"
        0x74656c6c6f7243757272656e744174746573746174696f6e0000000000000000;
    // For tellor mainnet, this is "0x636865636b706f696e7400000000000000000000000000000000000000000000". 
    // Otherwise, we take the tellor chain id as a string, and the validator set domain separator is 
    // keccak256(abi.encode("checkpoint", TELLOR_CHAIN_ID)). This differentiates between different networks.
    bytes32 public immutable VALIDATOR_SET_HASH_DOMAIN_SEPARATOR;

    /*Events*/
    event GuardianResetValidatorSet(uint256 _powerThreshold, uint256 _validatorTimestamp, bytes32 _validatorSetHash);
    event ValidatorSetUpdated(uint256 _powerThreshold, uint256 _validatorTimestamp, bytes32 _validatorSetHash);

    /*Errors*/
    error AlreadyInitialized();
    error InsufficientVotingPower();
    error InvalidPowerThreshold();
    error InvalidSignature();
    error MalformedCurrentValidatorSet();
    error NotDeployer();
    error NotGuardian();
    error StaleValidatorSet();
    error SuppliedValidatorSetInvalid();
    error ValidatorSetNotStale();
    error ValidatorTimestampMustIncrease();

    /*Functions*/
    /// @notice Constructor for the TellorDataBridge contract.
    /// @param _guardian Guardian address.
    constructor(
        address _guardian,
        bytes32 _validatorSetHashDomainSeparator
    ) {
        guardian = _guardian;
        deployer = msg.sender;
        VALIDATOR_SET_HASH_DOMAIN_SEPARATOR = _validatorSetHashDomainSeparator;
    }

    /// @notice This function is called only once by the deployer to initialize the contract
    /// @param _powerThreshold Initial voting power that is needed to approve operations
    /// @param _validatorTimestamp Timestamp of the block where validator set is updated.
    /// @param _unbondingPeriod Time period after which a validator can withdraw their stake.
    /// @param _validatorSetCheckpoint Initial checkpoint of the validator set.
    function init(
        uint256 _powerThreshold,
        uint256 _validatorTimestamp,
        uint256 _unbondingPeriod,
        bytes32 _validatorSetCheckpoint
    ) external {
        if (msg.sender != deployer) {
            revert NotDeployer();
        }
        if (initialized) {
            revert AlreadyInitialized();
        }
        initialized = true;
        powerThreshold = _powerThreshold;
        validatorTimestamp = _validatorTimestamp;
        unbondingPeriod = _unbondingPeriod;
        lastValidatorSetCheckpoint = _validatorSetCheckpoint;
    }

    /// @notice This function is called by the guardian to reset the validator set
    /// only if it becomes stale.
    /// @param _powerThreshold Amount of voting power needed to approve operations.
    /// @param _validatorTimestamp The timestamp of the block where validator set is updated.
    /// @param _validatorSetCheckpoint The hash of the validator set.
    function guardianResetValidatorSet(
        uint256 _powerThreshold,
        uint256 _validatorTimestamp,
        bytes32 _validatorSetCheckpoint
    ) external {
        if (msg.sender != guardian) {
            revert NotGuardian();
        }
        if (block.timestamp - (validatorTimestamp / MS_PER_SECOND) < unbondingPeriod) {
            revert ValidatorSetNotStale();
        }
        if (_validatorTimestamp <= validatorTimestamp) {
            revert ValidatorTimestampMustIncrease();
        }
        powerThreshold = _powerThreshold;
        validatorTimestamp = _validatorTimestamp;
        lastValidatorSetCheckpoint = _validatorSetCheckpoint;
        emit GuardianResetValidatorSet(_powerThreshold, _validatorTimestamp, _validatorSetCheckpoint);
    }

    /// @notice This updates the validator set by checking that the validators
    /// in the current validator set have signed off on the new validator set.
    /// @param _newValidatorSetHash The hash of the new validator set.
    /// @param _newPowerThreshold At least this much power must have signed.
    /// @param _newValidatorTimestamp The timestamp of the block where validator set is updated.
    /// @param _currentValidatorSet The current validator set.
    /// @param _sigs Signatures.
    function updateValidatorSet(
        bytes32 _newValidatorSetHash,
        uint64 _newPowerThreshold,
        uint256 _newValidatorTimestamp,
        Validator[] calldata _currentValidatorSet,
        Signature[] calldata _sigs
    ) external {
        if (_currentValidatorSet.length != _sigs.length) {
            revert MalformedCurrentValidatorSet();
        }
        if (_newValidatorTimestamp < validatorTimestamp) {
            revert ValidatorTimestampMustIncrease();
        }
        if (_newPowerThreshold == 0) {
            revert InvalidPowerThreshold();
        }
        // Check that the supplied current validator set matches the saved checkpoint.
        bytes32 _currentValidatorSetHash = keccak256(abi.encode(_currentValidatorSet));
        if (
            _domainSeparateValidatorSetHash(
                powerThreshold,
                validatorTimestamp,
                _currentValidatorSetHash
            ) != lastValidatorSetCheckpoint
        ) {
            revert SuppliedValidatorSetInvalid();
        }

        bytes32 _newCheckpoint = _domainSeparateValidatorSetHash(
            _newPowerThreshold,
            _newValidatorTimestamp,
            _newValidatorSetHash
        );
        _checkValidatorSignatures(
            _currentValidatorSet,
            _sigs,
            _newCheckpoint,
            powerThreshold
        );
        lastValidatorSetCheckpoint = _newCheckpoint;
        powerThreshold = _newPowerThreshold;
        validatorTimestamp = _newValidatorTimestamp;
        emit ValidatorSetUpdated(
            _newPowerThreshold,
            _newValidatorTimestamp,
            _newValidatorSetHash
        );
    }

    /*Getter functions*/
    /// @notice This getter verifies a given piece of data vs Validator signatures
    /// @param _attestData The data being verified
    /// @param _currentValidatorSet array of current validator set
    /// @param _sigs Signatures.
    function verifyOracleData(
        OracleAttestationData calldata _attestData,
        Validator[] calldata _currentValidatorSet,
        Signature[] calldata _sigs
    ) external view{
        if (_currentValidatorSet.length != _sigs.length) {
            revert MalformedCurrentValidatorSet();
        }
        // Check that the supplied current validator set matches the saved checkpoint.
        if (
            _domainSeparateValidatorSetHash(
                powerThreshold,
                validatorTimestamp,
                keccak256(abi.encode(_currentValidatorSet))
            ) != lastValidatorSetCheckpoint
        ) {
            revert SuppliedValidatorSetInvalid();
        }
        bytes32 _dataDigest = keccak256(
                abi.encode(
                    NEW_REPORT_ATTESTATION_DOMAIN_SEPARATOR,
                    _attestData.queryId,
                    _attestData.report.value,
                    _attestData.report.timestamp,
                    _attestData.report.aggregatePower,
                    _attestData.report.previousTimestamp,
                    _attestData.report.nextTimestamp,
                    lastValidatorSetCheckpoint,
                    _attestData.attestationTimestamp,
                    _attestData.report.lastConsensusTimestamp
                )
            );
        _checkValidatorSignatures(
            _currentValidatorSet,
            _sigs,
            _dataDigest,
            powerThreshold
        );
    }

    /*Internal functions*/
    /// @dev Checks that enough voting power signed over a digest.
    /// It expects the signatures to be in the same order as the _currentValidators.
    /// @param _currentValidators The current validators.
    /// @param _sigs The current validators' signatures.
    /// @param _digest This is what we are checking they have signed.
    /// @param _powerThreshold At least this much power must have signed.
    function _checkValidatorSignatures(
        // The current validator set and their powers
        Validator[] calldata _currentValidators,
        Signature[] calldata _sigs,
        bytes32 _digest,
        uint256 _powerThreshold
    ) internal view {
        if (block.timestamp - (validatorTimestamp / MS_PER_SECOND) > unbondingPeriod) {
            revert StaleValidatorSet();
        }
        uint256 _cumulativePower = 0;
        for (uint256 _i = 0; _i < _currentValidators.length; _i++) {
            // If the signature is nil, then it's not present so continue.
            if (_sigs[_i].r == 0 && _sigs[_i].s == 0 && _sigs[_i].v == 0) {
                continue;
            }
            // Check that the current validator has signed off on the hash.
            if (!_verifySig(_currentValidators[_i].addr, _digest, _sigs[_i])) {
                revert InvalidSignature();
            }
            _cumulativePower += _currentValidators[_i].power;
            // Break early to avoid wasting gas.
            if (_cumulativePower >= _powerThreshold) {
                break;
            }
        }
        if (_cumulativePower < _powerThreshold) {
            revert InsufficientVotingPower();
        }
    }

    /// @dev A hash of all relevant information about the validator set.
    /// @param _powerThreshold Amount of voting power needed to approve operations. (2/3 of total)
    /// @param _validatorTimestamp The timestamp of the block where validator set is updated.
    /// @param _validatorSetHash Validator set hash.
    /// @return The domain separated hash of the validator set.
    function _domainSeparateValidatorSetHash(
        uint256 _powerThreshold,
        uint256 _validatorTimestamp,
        bytes32 _validatorSetHash
    ) internal view returns (bytes32) {
        return
            keccak256(
                abi.encode(
                    VALIDATOR_SET_HASH_DOMAIN_SEPARATOR,
                    _powerThreshold,
                    _validatorTimestamp,
                    _validatorSetHash
                )
            );
    }

    /// @notice Utility function to verify Tellor Layer signatures
    /// @param _signer The address that signed the message.
    /// @param _digest The digest that was signed.
    /// @param _sig The signature.
    /// @return bool True if the signature is valid.
    function _verifySig(
        address _signer,
        bytes32 _digest,
        Signature calldata _sig
    ) internal pure returns (bool) {
        _digest = sha256(abi.encodePacked(_digest));
        (address _recovered, RecoverError error, ) = tryRecover(_digest, _sig.v, _sig.r, _sig.s);
        if (error != RecoverError.NoError) {
            revert InvalidSignature();
        }
        return _signer == _recovered;
    }
}

contracts/databank/ManualBackupOracle.so.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.19;

import {IBackupOracle} from "../interfaces/IBackupOracle.sol";

/**
 * @title ManualBackupOracle
 * @notice Admin-set price source that Shepherd can switch to after a challenge.
 */
contract ManualBackupOracle is IBackupOracle {
    address public admin;
    uint256 public value;
    uint256 public lastUpdatedAt;
    bool public readyToReturn;

    error NotAdmin();
    error InvalidAdmin();
    error PriceUnset();

    event ValueSet(uint256 value, uint256 timestamp);
    event ReadyToReturnSet(bool ready);

    constructor(address _admin) {
        if (_admin == address(0)) revert InvalidAdmin();
        admin = _admin;
    }

    function setValue(uint256 _value) external {
        if (msg.sender != admin) revert NotAdmin();
        value = _value;
        lastUpdatedAt = block.timestamp;
        emit ValueSet(_value, lastUpdatedAt);
    }

    function setReadyToReturn(bool _ready) external {
        if (msg.sender != admin) revert NotAdmin();
        readyToReturn = _ready;
        emit ReadyToReturnSet(_ready);
    }

    function getCurrentValue()
        external
        view
        override
        returns (uint256, uint256)
    {
        if (lastUpdatedAt == 0) revert PriceUnset();
        return (value, lastUpdatedAt);
    }
}

contracts/databank/TellorDataBank.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.19;

import "../interfaces/ITellorDataBridge.sol";
import {ITellorDataBank} from "../interfaces/ITellorDataBank.sol";

/**
 * @title TellorDataBank
 * @notice Verifies and stores Tellor SpotPrice reports and exposes historical TWAP reads.
 * @dev Relay timestamps govern when data became visible on this chain. Aggregate timestamps
 *      govern how long a reported price is weighted in the cumulative-price accumulator.
 */
contract TellorDataBank is ITellorDataBank {
    ITellorDataBridge public immutable dataBridge;
    uint256 public immutable MAX_DATA_AGE;
    uint256 public immutable MAX_ATTESTATION_AGE;
    uint256 public immutable OPTIMISTIC_DELAY;
    uint256 public immutable override MAX_SPOT_PRICE;

    uint256 public constant MS_PER_SECOND = 1000;

    mapping(bytes32 => AggregateData[]) public data;

    event OracleUpdated(bytes32 indexed queryId, OracleAttestationData attestData);

    constructor(
        address _dataBridge,
        uint256 _maxDataAge,
        uint256 _maxAttestationAge,
        uint256 _optimisticDelay,
        uint256 _maxSpotPrice
    ) {
        require(
            _dataBridge != address(0) && _dataBridge.code.length > 0,
            "TellorDataBank: Invalid bridge"
        );
        require(
            _maxSpotPrice > 0 &&
                _maxSpotPrice <= type(uint256).max / type(uint64).max,
            "TellorDataBank: Invalid max price"
        );

        dataBridge = ITellorDataBridge(_dataBridge);
        MAX_DATA_AGE = _maxDataAge;
        MAX_ATTESTATION_AGE = _maxAttestationAge;
        OPTIMISTIC_DELAY = _optimisticDelay;
        MAX_SPOT_PRICE = _maxSpotPrice;
    }

    /**
     * @notice Verifies and stores a Tellor SpotPrice report.
     * @dev Values must be ABI-encoded positive uint256 prices no greater than MAX_SPOT_PRICE.
     */
    function updateOracleData(
        OracleAttestationData calldata _attestData,
        Validator[] calldata _currentValidatorSet,
        Signature[] calldata _sigs
    ) external {
        _decodeSpotPrice(_attestData.report.value);
        _verifyOracleData(_attestData, _currentValidatorSet, _sigs);

        AggregateData[] storage _history = data[_attestData.queryId];
        uint256 _cumulativePrice;

        if (_history.length > 0) {
            AggregateData storage _previous = _history[_history.length - 1];
            uint256 _elapsed = _attestData.report.timestamp -
                _previous.aggregateTimestamp;
            uint256 _previousPrice = abi.decode(_previous.value, (uint256));
            _cumulativePrice =
                _previous.cumulativePrice +
                (_previousPrice * _elapsed);
        }

        _history.push(
            AggregateData({
                value: _attestData.report.value,
                power: _attestData.report.aggregatePower,
                aggregateTimestamp: _attestData.report.timestamp,
                attestationTimestamp: _attestData.attestationTimestamp,
                relayTimestamp: block.timestamp,
                cumulativePrice: _cumulativePrice
            })
        );

        emit OracleUpdated(_attestData.queryId, _attestData);
    }

    function getAggregateByIndex(bytes32 _queryId, uint256 _index)
        external
        view
        override
        returns (AggregateData memory)
    {
        return data[_queryId][_index];
    }

    function getAggregateValueCount(bytes32 _queryId)
        external
        view
        override
        returns (uint256)
    {
        return data[_queryId].length;
    }

    function getCurrentAggregateData(bytes32 _queryId)
        external
        view
        override
        returns (AggregateData memory)
    {
        return _getCurrentAggregateData(_queryId);
    }

    function getRelayBefore(bytes32 _queryId, uint256 _timestamp)
        external
        view
        override
        returns (bool _found, AggregateData memory _aggregateData)
    {
        (bool _indexFound, uint256 _index) = getIndexForRelayBefore(
            _queryId,
            _timestamp
        );
        if (!_indexFound) return (false, _emptyAggregateData());
        return (true, data[_queryId][_index]);
    }

    function getIndexForRelayBefore(bytes32 _queryId, uint256 _timestamp)
        public
        view
        override
        returns (bool _found, uint256 _index)
    {
        uint256 _count = data[_queryId].length;
        if (_count == 0 || data[_queryId][0].relayTimestamp >= _timestamp) {
            return (false, 0);
        }

        uint256 _end = _count - 1;
        if (data[_queryId][_end].relayTimestamp < _timestamp) {
            return (true, _end);
        }

        uint256 _start;
        while (_start < _end) {
            uint256 _middle = (_start + _end + 1) / 2;
            if (data[_queryId][_middle].relayTimestamp < _timestamp) {
                _start = _middle;
            } else {
                _end = _middle - 1;
            }
        }
        return (true, _start);
    }

    function getTwapAt(bytes32 _queryId, uint256 _endIndex, uint256 _window)
        external
        view
        override
        returns (bool _found, TwapData memory _twapData)
    {
        return _getTwapAt(_queryId, _endIndex, _window);
    }

    function getTwap(bytes32 _queryId, uint256 _window)
        external
        view
        override
        returns (bool _found, TwapData memory _twapData)
    {
        uint256 _count = data[_queryId].length;
        if (_count == 0) return (false, _emptyTwapData());
        return _getTwapAt(_queryId, _count - 1, _window);
    }

    function getRelayWithTwapBefore(
        bytes32 _queryId,
        uint256 _relayCutoff,
        uint256 _window
    )
        external
        view
        override
        returns (
            bool _found,
            uint256 _index,
            AggregateData memory _aggregateData,
            TwapData memory _twapData
        )
    {
        (bool _relayFound, uint256 _relayIndex) = getIndexForRelayBefore(
            _queryId,
            _relayCutoff
        );
        if (!_relayFound) {
            return (false, 0, _emptyAggregateData(), _emptyTwapData());
        }

        (bool _twapFound, TwapData memory _twap) = _getTwapAt(
            _queryId,
            _relayIndex,
            _window
        );
        if (!_twapFound) {
            return (
                false,
                _relayIndex,
                data[_queryId][_relayIndex],
                _emptyTwapData()
            );
        }

        return (
            true,
            _relayIndex,
            data[_queryId][_relayIndex],
            _twap
        );
    }

    function getRelayTimestampbyQueryIdandIndex(
        bytes32 _queryId,
        uint256 _index
    ) external view returns (uint256) {
        return data[_queryId][_index].relayTimestamp;
    }

    function _getTwapAt(
        bytes32 _queryId,
        uint256 _endIndex,
        uint256 _window
    ) internal view returns (bool _found, TwapData memory _twapData) {
        AggregateData[] storage _history = data[_queryId];
        if (_window == 0 || _endIndex >= _history.length || _endIndex == 0) {
            return (false, _emptyTwapData());
        }

        AggregateData storage _endObservation = _history[_endIndex];
        if (_endObservation.aggregateTimestamp < _window) {
            return (false, _emptyTwapData());
        }

        uint256 _targetTimestamp =
            _endObservation.aggregateTimestamp -
            _window;
        (bool _startFound, uint256 _startIndex) = _getIndexForAggregateAtOrBefore(
            _queryId,
            _targetTimestamp,
            _endIndex
        );
        if (!_startFound || _startIndex == _endIndex) {
            return (false, _emptyTwapData());
        }

        AggregateData storage _startObservation = _history[_startIndex];
        uint256 _elapsed =
            _endObservation.aggregateTimestamp -
            _startObservation.aggregateTimestamp;
        uint256 _cumulativeDelta =
            _endObservation.cumulativePrice -
            _startObservation.cumulativePrice;

        return (
            true,
            TwapData({
                price: _cumulativeDelta / _elapsed,
                startAggregateTimestamp: _startObservation.aggregateTimestamp,
                endAggregateTimestamp: _endObservation.aggregateTimestamp,
                observationCount: _endIndex - _startIndex + 1
            })
        );
    }

    function _getIndexForAggregateAtOrBefore(
        bytes32 _queryId,
        uint256 _timestamp,
        uint256 _endIndex
    ) internal view returns (bool _found, uint256 _index) {
        AggregateData[] storage _history = data[_queryId];
        if (
            _history.length == 0 ||
            _endIndex >= _history.length ||
            _history[0].aggregateTimestamp > _timestamp
        ) {
            return (false, 0);
        }

        uint256 _start;
        uint256 _end = _endIndex;
        while (_start < _end) {
            uint256 _middle = (_start + _end + 1) / 2;
            if (_history[_middle].aggregateTimestamp <= _timestamp) {
                _start = _middle;
            } else {
                _end = _middle - 1;
            }
        }
        return (true, _start);
    }

    function _decodeSpotPrice(bytes calldata _value)
        internal
        view
        returns (uint256 _price)
    {
        require(_value.length == 32, "TellorDataBank: Invalid SpotPrice");
        _price = abi.decode(_value, (uint256));
        require(
            _price > 0 && _price <= MAX_SPOT_PRICE,
            "TellorDataBank: SpotPrice out of range"
        );
    }

    function _getCurrentAggregateData(bytes32 _queryId)
        internal
        view
        returns (AggregateData memory)
    {
        uint256 _count = data[_queryId].length;
        if (_count == 0) return _emptyAggregateData();
        return data[_queryId][_count - 1];
    }

    function _emptyAggregateData()
        internal
        pure
        returns (AggregateData memory)
    {
        return AggregateData(bytes(""), 0, 0, 0, 0, 0);
    }

    function _emptyTwapData() internal pure returns (TwapData memory) {
        return TwapData(0, 0, 0, 0);
    }

    function _verifyOracleData(
        OracleAttestationData calldata _attestData,
        Validator[] calldata _currentValidatorSet,
        Signature[] calldata _sigs
    ) internal view {
        uint256 _reportTimestamp =
            _attestData.report.timestamp /
            MS_PER_SECOND;
        uint256 _attestationTimestamp =
            _attestData.attestationTimestamp /
            MS_PER_SECOND;

        require(
            _reportTimestamp <= block.timestamp,
            "TellorDataBank: Report timestamp is in the future"
        );
        require(
            _attestationTimestamp <= block.timestamp,
            "TellorDataBank: Attestation timestamp is in the future"
        );
        require(
            block.timestamp - _reportTimestamp < MAX_DATA_AGE,
            "TellorDataBank: Data too old"
        );
        require(
            block.timestamp - _attestationTimestamp < MAX_ATTESTATION_AGE,
            "TellorDataBank: Attestation too old"
        );

        AggregateData memory _previousData = _getCurrentAggregateData(
            _attestData.queryId
        );
        if (_previousData.aggregateTimestamp > 0) {
            require(
                _attestData.report.timestamp >
                    _previousData.aggregateTimestamp,
                "TellorDataBank: Report timestamp must increase"
            );
        }

        if (_attestData.report.nextTimestamp != 0) {
            uint256 _nextTimestamp =
                _attestData.report.nextTimestamp /
                MS_PER_SECOND;
            require(
                _nextTimestamp <= block.timestamp &&
                    block.timestamp - _nextTimestamp < OPTIMISTIC_DELAY,
                "TellorDataBank: More recent optimistic report available"
            );
        }

        if (
            _attestData.report.timestamp !=
            _attestData.report.lastConsensusTimestamp
        ) {
            require(
                _attestData.attestationTimestamp >=
                    _attestData.report.timestamp,
                "TellorDataBank: Invalid attestation timestamp"
            );
            require(
                _attestData.report.lastConsensusTimestamp <
                    _attestData.report.timestamp,
                "TellorDataBank: Newer consensus data available"
            );
            require(
                (_attestData.attestationTimestamp -
                    _attestData.report.timestamp) /
                    MS_PER_SECOND >=
                    OPTIMISTIC_DELAY,
                "TellorDataBank: Dispute period not passed"
            );
            require(
                _attestData.report.aggregatePower >
                    dataBridge.powerThreshold() /
                    2,
                "TellorDataBank: Insufficient optimistic report power"
            );
        }

        dataBridge.verifyOracleData(
            _attestData,
            _currentValidatorSet,
            _sigs
        );
    }
}

contracts/databank/TellorShepherd.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.19;

import {IBackupOracle} from "../interfaces/IBackupOracle.sol";
import {ITellorDataBank} from "../interfaces/ITellorDataBank.sol";
import {ITellorShepherd} from "../interfaces/ITellorShepherd.sol";

/**
 * @title TellorShepherd
 * @notice A view-first safety layer for one Tellor SpotPrice query.
 * @dev Reads use a delayed DataBank relay. A persistent TWAP deviation can be
 *      challenged permissionlessly; after the delay, a still-deviant feed
 *      switches to the constructor-set backup oracle until that oracle says
 *      it is safe to return.
 */
contract TellorShepherd is ITellorShepherd {
    uint256 public constant BPS_DENOMINATOR = 10_000;

    struct Parameters {
        // EVM-time seconds.
        uint256 relayConsumptionDelay;
        // Tellor aggregate-time milliseconds.
        uint256 twapWindow;
        uint256 minTwapCoverage;
        uint256 maxTwapCoverage;
        uint256 minTwapObservations;
        uint256 deviationThresholdBps;
        uint256 challengeDelay;
        uint256 unpauseDelay;
        uint256 dataBankChangeDelay;
        uint256 roleChangeDelay;
        uint256 adminTransferDelay;
    }

    ITellorDataBank public dataBank;
    IBackupOracle public immutable backupOracle;
    address public admin;
    bytes32 public immutable queryId;

    uint256 public immutable RELAY_CONSUMPTION_DELAY; // EVM-time seconds
    // The following three values use Tellor aggregate-time milliseconds.
    uint256 public immutable TWAP_WINDOW;
    uint256 public immutable MIN_TWAP_COVERAGE;
    uint256 public immutable MAX_TWAP_COVERAGE;
    uint256 public immutable MIN_TWAP_OBSERVATIONS;
    uint256 public immutable DEVIATION_THRESHOLD_BPS;
    uint256 public immutable CHALLENGE_DELAY;
    uint256 public immutable UNPAUSE_DELAY;
    uint256 public immutable DATA_BANK_CHANGE_DELAY;
    uint256 public immutable ROLE_CHANGE_DELAY;
    uint256 public immutable ADMIN_TRANSFER_DELAY;

    bool public paused;
    bool public usingBackup;
    uint256 public challengeStartTime;

    mapping(address => bool) public pausers;
    mapping(address => uint256) public pauserAdditionProposalTime;

    uint256 public unpauseProposalTime;
    address public proposedDataBank;
    uint256 public dataBankProposalTime;
    address public proposedAdmin;
    uint256 public adminTransferProposalTime;

    error InvalidConfiguration();
    error NotAdmin();
    error NotPauser();
    error ShepherdPaused();
    error PriceUnavailable(Status status);
    error InvalidProposal();
    error DelayNotPassed();
    error ChallengeNotRequired();
    error ChallengePending();
    error NoChallenge();
    error UsingBackup();
    error BackupNotReady();

    event Paused(address indexed account);
    event Unpaused();
    event UnpauseProposed(uint256 executableAt);
    event UnpauseCancelled();

    event ChallengeOpened(address indexed challenger, uint256 executableAt);
    event ChallengeCleared(address indexed account);
    event ChallengeExecuted(
        address indexed account,
        uint256 candidateValue,
        uint256 twap,
        uint256 deviationBps
    );
    event ReturnedToPrimary(address indexed account);

    event PauserAdditionProposed(address indexed account, uint256 executableAt);
    event PauserAdded(address indexed account);
    event PauserRemoved(address indexed account);

    event DataBankChangeProposed(
        address indexed proposedDataBank,
        uint256 executableAt
    );
    event DataBankChangeCancelled();
    event DataBankChanged(
        address indexed oldDataBank,
        address indexed newDataBank
    );
    event AdminTransferProposed(
        address indexed proposedAdmin,
        uint256 executableAt
    );
    event AdminTransferCancelled();
    event AdminTransferred(address indexed oldAdmin, address indexed newAdmin);

    constructor(
        address _dataBank,
        address _admin,
        address _backupOracle,
        bytes32 _queryId,
        Parameters memory _parameters,
        address[] memory _pausers
    ) {
        if (
            _dataBank == address(0) ||
            _dataBank.code.length == 0 ||
            _admin == address(0) ||
            _backupOracle == address(0) ||
            _queryId == bytes32(0) ||
            _parameters.twapWindow == 0 ||
            _parameters.minTwapCoverage == 0 ||
            _parameters.minTwapCoverage > _parameters.twapWindow ||
            _parameters.maxTwapCoverage < _parameters.twapWindow ||
            _parameters.minTwapObservations < 2 ||
            _parameters.deviationThresholdBps == 0 ||
            _parameters.deviationThresholdBps > BPS_DENOMINATOR
        ) revert InvalidConfiguration();

        dataBank = ITellorDataBank(_dataBank);
        backupOracle = IBackupOracle(_backupOracle);
        admin = _admin;
        queryId = _queryId;

        RELAY_CONSUMPTION_DELAY = _parameters.relayConsumptionDelay;
        TWAP_WINDOW = _parameters.twapWindow;
        MIN_TWAP_COVERAGE = _parameters.minTwapCoverage;
        MAX_TWAP_COVERAGE = _parameters.maxTwapCoverage;
        MIN_TWAP_OBSERVATIONS = _parameters.minTwapObservations;
        DEVIATION_THRESHOLD_BPS = _parameters.deviationThresholdBps;
        CHALLENGE_DELAY = _parameters.challengeDelay;
        UNPAUSE_DELAY = _parameters.unpauseDelay;
        DATA_BANK_CHANGE_DELAY = _parameters.dataBankChangeDelay;
        ROLE_CHANGE_DELAY = _parameters.roleChangeDelay;
        ADMIN_TRANSFER_DELAY = _parameters.adminTransferDelay;

        for (uint256 i; i < _pausers.length; ++i) {
            _addInitialRole(_pausers[i], pausers);
            emit PauserAdded(_pausers[i]);
        }
    }

    // ---------------------------------------------------------------------
    // Price reads
    // ---------------------------------------------------------------------

    function getCurrentValue()
        external
        view
        override
        returns (uint256 _value, uint256 _aggregateTimestamp)
    {
        if (paused) revert ShepherdPaused();

        if (usingBackup) {
            return backupOracle.getCurrentValue();
        }

        PricePreview memory _preview = _previewNormalValue();
        if (
            _preview.status != Status.NORMAL &&
            _preview.status != Status.DEVIATING
        ) {
            revert PriceUnavailable(_preview.status);
        }
        return (
            _preview.candidateValue,
            _preview.candidateAggregateTimestamp
        );
    }

    function previewValue()
        external
        view
        override
        returns (PricePreview memory _preview)
    {
        if (paused) {
            _preview.status = Status.PAUSED;
            return _preview;
        }

        if (usingBackup) {
            (
                uint256 _value,
                uint256 _timestamp
            ) = backupOracle.getCurrentValue();
            _preview.status = Status.BACKUP;
            _preview.candidateValue = _value;
            _preview.candidateAggregateTimestamp = _timestamp;
            return _preview;
        }

        _preview = _previewNormalValue();
        if (challengeStartTime != 0) {
            _preview.status = Status.CHALLENGING;
        }
    }

    // ---------------------------------------------------------------------
    // Challenge
    // ---------------------------------------------------------------------

    /**
     * @notice Starts the challenge delay when the delayed relay exceeds the TWAP threshold.
     * @dev Reads continue to return the delayed DataBank relay until `executeChallenge`.
     */
    function challenge() external {
        if (usingBackup) revert UsingBackup();
        if (challengeStartTime != 0) revert ChallengePending();
        if (_previewNormalValue().status != Status.DEVIATING) {
            revert ChallengeNotRequired();
        }

        challengeStartTime = block.timestamp;
        emit ChallengeOpened(msg.sender, block.timestamp + CHALLENGE_DELAY);
    }

    /**
     * @notice Completes a matured challenge. Switches to the backup oracle if still deviant.
     */
    function executeChallenge() external {
        if (usingBackup) revert UsingBackup();
        if (challengeStartTime == 0) revert NoChallenge();
        if (block.timestamp < challengeStartTime + CHALLENGE_DELAY) {
            revert DelayNotPassed();
        }

        PricePreview memory _preview = _previewNormalValue();
        if (_preview.status != Status.DEVIATING) {
            delete challengeStartTime;
            emit ChallengeCleared(msg.sender);
            return;
        }

        backupOracle.getCurrentValue();
        usingBackup = true;
        delete challengeStartTime;
        emit ChallengeExecuted(
            msg.sender,
            _preview.candidateValue,
            _preview.twap,
            _preview.deviationBps
        );
    }

    /**
     * @notice Returns to delayed Tellor data once the backup oracle signals it is safe.
     */
    function returnToPrimary() external {
        if (!usingBackup) revert InvalidProposal();
        if (!backupOracle.readyToReturn()) revert BackupNotReady();

        usingBackup = false;
        emit ReturnedToPrimary(msg.sender);
    }

    // ---------------------------------------------------------------------
    // Pause controls
    // ---------------------------------------------------------------------

    function pause() external {
        if (msg.sender != admin && !pausers[msg.sender]) revert NotPauser();
        if (paused) revert InvalidProposal();

        paused = true;
        delete unpauseProposalTime;
        emit Paused(msg.sender);
    }

    function proposeUnpause() external onlyAdmin {
        if (!paused || unpauseProposalTime != 0) revert InvalidProposal();
        unpauseProposalTime = block.timestamp;
        emit UnpauseProposed(block.timestamp + UNPAUSE_DELAY);
    }

    function cancelUnpause() external onlyAdmin {
        if (unpauseProposalTime == 0) revert InvalidProposal();
        delete unpauseProposalTime;
        emit UnpauseCancelled();
    }

    function executeUnpause() external onlyAdmin {
        if (!paused || unpauseProposalTime == 0) revert InvalidProposal();
        if (block.timestamp < unpauseProposalTime + UNPAUSE_DELAY) {
            revert DelayNotPassed();
        }

        paused = false;
        delete unpauseProposalTime;
        emit Unpaused();
    }

    // ---------------------------------------------------------------------
    // Roles
    // ---------------------------------------------------------------------

    function proposePauser(address _account) external onlyAdmin {
        _proposeRole(_account, pauserAdditionProposalTime, pausers);
        emit PauserAdditionProposed(
            _account,
            block.timestamp + ROLE_CHANGE_DELAY
        );
    }

    function executePauser(address _account) external {
        _executeRole(_account, pauserAdditionProposalTime, pausers);
        emit PauserAdded(_account);
    }

    function removePauser(address _account) external onlyAdmin {
        if (!pausers[_account]) revert InvalidProposal();
        pausers[_account] = false;
        emit PauserRemoved(_account);
    }

    // ---------------------------------------------------------------------
    // DataBank and admin changes
    // ---------------------------------------------------------------------

    function proposeDataBank(address _newDataBank) external onlyAdmin {
        if (
            proposedDataBank != address(0) ||
            _newDataBank == address(0) ||
            _newDataBank.code.length == 0 ||
            _newDataBank == address(dataBank)
        ) revert InvalidProposal();

        proposedDataBank = _newDataBank;
        dataBankProposalTime = block.timestamp;
        emit DataBankChangeProposed(
            _newDataBank,
            block.timestamp + DATA_BANK_CHANGE_DELAY
        );
    }

    function cancelDataBankChange() external onlyAdmin {
        if (proposedDataBank == address(0)) revert InvalidProposal();
        delete proposedDataBank;
        delete dataBankProposalTime;
        emit DataBankChangeCancelled();
    }

    function executeDataBankChange() external onlyAdmin {
        if (proposedDataBank == address(0)) revert InvalidProposal();
        if (block.timestamp < dataBankProposalTime + DATA_BANK_CHANGE_DELAY) {
            revert DelayNotPassed();
        }
        if (!paused) revert ShepherdPaused();

        address _oldDataBank = address(dataBank);
        dataBank = ITellorDataBank(proposedDataBank);
        delete proposedDataBank;
        delete dataBankProposalTime;
        emit DataBankChanged(_oldDataBank, address(dataBank));
    }

    function proposeAdmin(address _newAdmin) external onlyAdmin {
        if (_newAdmin == address(0) || proposedAdmin != address(0)) {
            revert InvalidProposal();
        }
        proposedAdmin = _newAdmin;
        adminTransferProposalTime = block.timestamp;
        emit AdminTransferProposed(
            _newAdmin,
            block.timestamp + ADMIN_TRANSFER_DELAY
        );
    }

    function cancelAdminTransfer() external onlyAdmin {
        if (proposedAdmin == address(0)) revert InvalidProposal();
        delete proposedAdmin;
        delete adminTransferProposalTime;
        emit AdminTransferCancelled();
    }

    function acceptAdmin() external {
        if (msg.sender != proposedAdmin) revert NotAdmin();
        if (
            block.timestamp <
            adminTransferProposalTime + ADMIN_TRANSFER_DELAY
        ) revert DelayNotPassed();

        address _oldAdmin = admin;
        admin = msg.sender;
        delete proposedAdmin;
        delete adminTransferProposalTime;
        emit AdminTransferred(_oldAdmin, msg.sender);
    }

    // ---------------------------------------------------------------------
    // Internal price evaluation
    // ---------------------------------------------------------------------

    function _previewNormalValue()
        internal
        view
        returns (PricePreview memory _preview)
    {
        if (block.timestamp <= RELAY_CONSUMPTION_DELAY) return _preview;

        (
            bool _found,
            uint256 _index,
            ITellorDataBank.AggregateData memory _data,
            ITellorDataBank.TwapData memory _twap
        ) = dataBank.getRelayWithTwapBefore(
                queryId,
                block.timestamp - RELAY_CONSUMPTION_DELAY,
                TWAP_WINDOW
            );

        if (!_found) return _preview;
        return _evaluate(_index, _data, _twap);
    }

    function _evaluate(
        uint256 _index,
        ITellorDataBank.AggregateData memory _data,
        ITellorDataBank.TwapData memory _twap
    ) internal view returns (PricePreview memory _preview) {
        _preview.candidateIndex = _index;
        _preview.candidateAggregateTimestamp = _data.aggregateTimestamp;
        _preview.candidateRelayTimestamp = _data.relayTimestamp;
        _preview.twap = _twap.price;
        _preview.twapStartTimestamp = _twap.startAggregateTimestamp;
        _preview.twapEndTimestamp = _twap.endAggregateTimestamp;
        _preview.observationCount = _twap.observationCount;

        uint256 _maxSpotPrice = dataBank.MAX_SPOT_PRICE();
        if (
            _data.value.length != 32 ||
            _twap.price == 0 ||
            _twap.price > _maxSpotPrice
        ) {
            _preview.status = Status.INVALID_PRICE;
            return _preview;
        }
        _preview.candidateValue = abi.decode(_data.value, (uint256));
        if (
            _preview.candidateValue == 0 ||
            _preview.candidateValue > _maxSpotPrice
        ) {
            _preview.status = Status.INVALID_PRICE;
            return _preview;
        }

        uint256 _coverage =
            _twap.endAggregateTimestamp -
            _twap.startAggregateTimestamp;
        if (
            _coverage < MIN_TWAP_COVERAGE ||
            _coverage > MAX_TWAP_COVERAGE ||
            _twap.observationCount < MIN_TWAP_OBSERVATIONS
        ) {
            _preview.status = Status.INVALID_COVERAGE;
            return _preview;
        }

        _preview.deviationBps = _calculateDeviationBps(
            _preview.candidateValue,
            _twap.price
        );
        _preview.status = _preview.deviationBps > DEVIATION_THRESHOLD_BPS
            ? Status.DEVIATING
            : Status.NORMAL;
    }

    function _calculateDeviationBps(uint256 _value, uint256 _reference)
        internal
        pure
        returns (uint256)
    {
        uint256 _difference = _value > _reference
            ? _value - _reference
            : _reference - _value;
        if (_difference > type(uint256).max / BPS_DENOMINATOR) {
            return type(uint256).max;
        }
        return (_difference * BPS_DENOMINATOR) / _reference;
    }

    // ---------------------------------------------------------------------
    // Internal administration
    // ---------------------------------------------------------------------

    function _addInitialRole(
        address _account,
        mapping(address => bool) storage _role
    ) internal {
        if (_account == address(0)) revert InvalidConfiguration();
        _role[_account] = true;
    }

    function _proposeRole(
        address _account,
        mapping(address => uint256) storage _proposalTime,
        mapping(address => bool) storage _role
    ) internal {
        if (
            _account == address(0) ||
            _role[_account] ||
            _proposalTime[_account] != 0
        ) revert InvalidProposal();
        _proposalTime[_account] = block.timestamp;
    }

    function _executeRole(
        address _account,
        mapping(address => uint256) storage _proposalTime,
        mapping(address => bool) storage _role
    ) internal {
        uint256 _proposedAt = _proposalTime[_account];
        if (_proposedAt == 0) revert InvalidProposal();
        if (block.timestamp < _proposedAt + ROLE_CHANGE_DELAY) {
            revert DelayNotPassed();
        }
        _role[_account] = true;
        delete _proposalTime[_account];
    }

    modifier onlyAdmin() {
        if (msg.sender != admin) revert NotAdmin();
        _;
    }
}

contracts/examples/YoloTellorUser.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.19;

import "../interfaces/ITellorDataBridge.sol";

// This contract shows a baseline oracle user that just verifies the data is valid tellor data
// and stores the data for retrieval. It should never be used in production.

contract YoloTellorUser {
    ITellorDataBridge public dataBridge;
    bytes32 public queryId;
    OracleData[] public oracleData;

    struct OracleData {
        uint256 value;
        uint256 timestamp;
    }

    // sets the tellor data bridge address and the queryId
    constructor(address _dataBridge, bytes32 _queryId) {
        dataBridge = ITellorDataBridge(_dataBridge);
        queryId = _queryId;
    }

    // updates this contract with new oracle data using the data bridge
    // production users should add security checks
    function updateOracleData(
        OracleAttestationData calldata _attestData,
        Validator[] calldata _currentValidatorSet,
        Signature[] calldata _sigs
    ) external {
        // make sure the data is valid tellor data
        dataBridge.verifyOracleData(_attestData, _currentValidatorSet, _sigs);
        // make sure the data being relayed is the data we want
        require(queryId == _attestData.queryId, "Invalid queryId");

        // decode the data and store it
        uint256 _value = abi.decode(_attestData.report.value, (uint256));
        oracleData.push(OracleData(_value, _attestData.report.timestamp));
    }

    // returns the most recent data
    function getCurrentData() external view returns (OracleData memory) {
        return oracleData[oracleData.length - 1];
    }

    // returns the number of data points stored
    function getValueCount() external view returns (uint256) {
        return oracleData.length;
    }
}

